// ---------------------------------------------------------------------------
// Reading the table
// ---------------------------------------------------------------------------

const BY_STEP = new Map(JOBS.map((j) => [`${j.id}#${j.step}`, j]));
/** One job step, or null. */
export const jobStep = (id: string, step = 0): UseJob | null => BY_STEP.get(`${id}#${step}`) ?? null;

/**
 * The job step each rail kind's page row reads (`withModuleModels`). The
 * canvas's fourteen kinds keep the shape of the run they already make: the
 * search and match pages run a chat model, so they read a job's research or
 * write step, never its embedder. The seven kinds #3934 adds read their own.
 */
export const RAIL_KIND_JOBS: Readonly<Record<string, { id: string; step: number }>> = Object.freeze({
  chat: { id: 'ST1', step: 0 }, synth: { id: 'ST2', step: 0 }, speech: { id: 'VA1', step: 0 }, research: { id: 'VA13', step: 0 },
  reason: { id: 'DK8', step: 0 }, vision: { id: 'BU6', step: 0 }, code: { id: 'BU5', step: 0 }, numbers: { id: 'RA8', step: 0 },
  write: { id: 'EM1', step: 0 }, match: { id: 'NE1', step: 2 }, plan: { id: 'BU2', step: 0 }, legal: { id: 'BU8', step: 0 },
  multi: { id: 'RE6', step: 0 }, search: { id: 'RE1', step: 2 },
  draw: { id: 'DK4', step: 0 }, edit_image: { id: 'DK5', step: 0 }, voice_turn: { id: 'ST9', step: 0 }, agent: { id: 'AG1', step: 0 },
  decide: { id: 'VA14', step: 0 }, sentiment: { id: 'ON5', step: 0 }, translate: { id: 'VA7', step: 0 },
  // D1583 (#3830): `derive:memo`'s option kind reads the IC memo job.
  memo: { id: 'IN1', step: 0 },
});

/**
 * Models §2 lists for a kind with a scope of their own: sea-lion for SEA
 * locales, r1-distill for Learning, indictrans2 for English into an Indic
 * language. They are offered only where a job names them, never as the rest
 * of their kind's list.
 */
export const SCOPED_MODELS: ReadonlySet<string> = new Set(['@cf/aisingapore/gemma-sea-lion-v4-27b-it', '@cf/deepseek-ai/deepseek-r1-distill-qwen-32b', '@cf/ai4bharat/indictrans2-en-indic-1B']);

/** What a locked model's card shows, or null when every plan runs it (A (c)). */
export const lockLabel = (id: string): string | null => {
  const lock = MODEL_LOCKS[id] ?? 'all';
  return lock === 'all' ? null : LOCK_LABELS[lock];
};

/** Never listed on a rail: a hidden model, or one waiting on Legal's read (D (a)). */
export const offerable = (id: string): boolean => (MODEL_LOCKS[id] ?? 'all') !== 'hidden' && !LEGAL_HOLD.has(id);

export type Card = { id: string; role: string; line: string };
export type Choice = { id: string; line: string };

/**
 * A job step as the rail shows it: at most three suggested models (Default,
 * Alternative, Deeper, in that order, roles by position), and every other
 * model the step or its kind lists under All models. `fits` says whether the
 * row's run can execute a model (its shape); `offerable` drops what no rail
 * lists. A fixed step suggests its one model and lists nothing more.
 */
/** #3935: every model a job's selector can show (its own models, then its kind's), before the offer filters: what a press may accept. */
export const jobChoices = (job: UseJob): string[] => [...new Set([job.default, job.alternative, job.deeper, job.fallback, ...job.more,
  ...USE_KINDS[job.kind].models.filter((id) => !SCOPED_MODELS.has(id))].filter((id): id is string => !!id))];

export function selectorFor(job: UseJob, fits: (id: string) => boolean): { models: Card[]; more: Choice[] } {
  const ok = (id: string | null): id is string => !!id && fits(id) && offerable(id);
  const roles = ['Default', 'Alternative', 'Deeper'];
  const picked = [job.default, job.alternative, job.deeper].filter(ok).filter((id, i, a) => a.indexOf(id) === i);
  // #3935: when none of the three can be offered (Legal holds them all, as GR3's Lucid and Phoenix), the
  // job's fallback is what runs, so it is the row's Default rather than an empty row.
  if (!picked.length && ok(job.fallback)) picked.push(job.fallback);
  const models = picked.map((id, i) => ({ id, role: roles[i], line: MODEL_LINES[id] ?? '' }));
  if (job.fixed) return { models: models.slice(0, 1), more: [] };
  const rest = [...job.more, ...USE_KINDS[job.kind].models.filter((id) => !SCOPED_MODELS.has(id))].filter(ok).filter((id, i, a) => a.indexOf(id) === i && !picked.includes(id));
  return { models, more: rest.map((id) => ({ id, line: MODEL_LINES[id] ?? '' })) };
}

// ---------------------------------------------------------------------------
// The deck's element groups (revision 4): one job per group and per item
// ---------------------------------------------------------------------------

